import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]/'courses/interview'
assert json.loads((ROOT/'course.json').read_text())['contentVersion']=='1.0.8', 'One-time transformation: do not reapply to a published revision.'
changes=[]
def revise(id,question,practice,correct,wrong,feedback,followup,lead=None,rule=None,example=None,caption=None):
 p=ROOT/'lessons'/f'{id}.json';r=json.loads(p.read_text());w=r['writing'];index=w['correctAnswer'];options=iter(wrong);w['answers']=[correct if i==index else next(options) for i in range(3)]
 w.update(question=question,practiceCode=practice,feedback=feedback)
 if lead:w['explanation']=lead+'\n\n'+w['explanation'].split('\n\n',1)[-1]
 if rule:w['rule']=rule
 if example:w['exampleCode']=example
 if caption:w['exampleCaption']=caption
 w['explanation']+='\n\nInterview follow-up: '+followup
 r['depth'].update(misconception=w['answers'][(index+1)%3],correction=feedback,transferChallenge=followup)
 r['depth']['traceSteps']=[{'title':'Identify the contract','detail':w['summary']},{'title':'Trace the concrete example','detail':w['exampleCaption']},{'title':'Test the changed constraint','detail':followup}]
 p.write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n');changes.append(id)
revise('q-ownership','Why is using s after take(s) rejected?', 'fn take(_: String) {}\nfn main() {\n    let s = String::from("x");\n    take(s);\n    println!("{s}"); // deliberate compile error\n}', 'The by-value call transfers ownership of s into the parameter.', ['Passing a String copies its buffer and leaves both owners usable.','The function signature creates a shared borrow lasting to main’s end.'], 'String is not Copy. take consumes this value; borrow &str instead if the helper only needs to read it.', 'When would cloning be appropriate? Explain its semantic and allocation cost, then name a situation where cleanup can be intentionally skipped.',lead='Ownership determines which value is responsible for a resource. Moves transfer that responsibility; Copy types can be duplicated implicitly, while Clone is explicit. Normal scope exit drops owned values, but memory safety does not promise that every destructor runs: forgetting values, reference cycles or process termination can skip cleanup.',rule='Ownership tracks resource responsibility; move, borrow and clone express different contracts.')
revise('q-borrowing','Which overlapping uses make this program fail to compile?', 'fn main() {\n    let mut v = vec![1];\n    let writer = &mut v;\n    let reader = &v;\n    println!("{writer:?} {reader:?}");\n}', 'The mutable borrow is still used after the shared borrow is created.', ['Declaring two references in one lexical scope is always forbidden.','Creating a reference to a Vec requires cloning its allocation first.'], 'Both references are used by println, so their live regions overlap. Without the later uses, the original abbreviated example could compile under non-lexical lifetimes.', 'Move the writer’s final use before creating reader. Why does that version compile without adding clone?',lead='Shared reads and exclusive mutation of the same memory cannot overlap incompatibly. Rust tracks the uses that keep each borrow live, rather than banning both reference kinds from one lexical scope. Interior mutability provides additional APIs whose safety rules must still be respected.')
revise('q-lifetimes','Why can no lifetime annotation make returning this reference valid?', 'fn dangle() -> &\'static str {\n    let text = String::from("local");\n    text.as_str() // deliberate compile error\n}\nfn main() {}', 'The returned reference would outlive the local String allocation.', ['An explicit static lifetime extends the local allocation’s storage.','Adding the same lifetime name to both bindings transfers ownership.'], 'Annotations describe relationships; they do not keep a local allocation alive. Return String or borrow storage supplied by the caller.', 'Rewrite the function to return an owned String, then explain why a string literal has a different lifetime.')
revise('q-option-result','Which conversion produces a Result and computes the error only for None?', 'fn main() {\n    let value: Option<u32> = Some(7);\n    let result = value.ok_or_else(|| String::from("missing"));\n    assert_eq!(result, Ok(7));\n}', 'ok_or_else supplies a lazily constructed error for an absent value.', ['unwrap_or_else preserves the Option in a new Result wrapper.','map_err transforms the error already stored inside an Option.'], 'Option has no error payload. ok_or takes an error value; ok_or_else takes a closure. A missing value can be normal or erroneous depending on the API.', 'How would Result<Option<T>, E> distinguish absence from failure? Explain how transpose changes the nesting.',example='use std::collections::HashMap;\nfn port(config: &HashMap<&str, &str>) -> Result<u16, String> {\n    config.get("port")\n        .ok_or_else(|| "port is missing".to_owned())?\n        .parse()\n        .map_err(|_| "port is not a u16".to_owned())\n}\nfn main() {\n    assert_eq!(port(&HashMap::from([("port", "8080")])), Ok(8080));\n}',caption='Missing configuration and an invalid number reach different explicit error paths.')
revise('q-send-sync','Why does moving this Rc into thread::spawn fail its Send bound?', 'fn main() {\n    let shared = std::rc::Rc::new(1);\n    std::thread::spawn(move || println!("{shared}"));\n}', 'Rc cannot transfer shared ownership across threads with its non-atomic count.', ['The move closure borrows shared instead of taking ownership of it.','Every thread closure must borrow its captures through a shared reference.'], 'Arc<T> is Send and Sync only when the relevant T: Send + Sync bounds hold. Atomic reference counting alone does not make T thread-safe.', 'Is Arc<RefCell<u32>> suitable for shared mutation across threads? Identify the missing Sync guarantee and a suitable alternative.',lead='Send permits ownership transfer across threads. Sync means that a shared reference can be sent safely; formally, T is Sync when &T is Send. Auto-trait implementations depend on the fields and inner types, so Arc alone cannot make an arbitrary payload thread-safe.')
revise('q-box-rc-arc','Which option expresses shared ownership on one thread without atomic reference counting?', 'struct Node { value: u32 }\nfn main() {\n    let first = std::rc::Rc::new(Node { value: 7 });\n    let second = std::rc::Rc::clone(&first);\n    assert_eq!(second.value, 7);\n}', 'Rc<Node> matches this single-threaded shared-ownership requirement.', ['Box<Node> gives several independent owners of the same allocation.','Arc<Node> avoids all reference-count operations because its count is atomic.'], 'Rc shares ownership on one thread. Arc also shares ownership, but uses atomic counts and only crosses threads when its inner bounds permit it.', 'Draw a strong reference cycle and replace a back-reference with Weak. Why does memory safety allow a leak?')
revise('q-dyn-generics','Which statement correctly describes passing &circle as &dyn Shape?', 'trait Shape { fn area(&self) -> u32; }\nstruct Square(u32);\nimpl Shape for Square { fn area(&self) -> u32 { self.0 * self.0 } }\nfn area(shape: &dyn Shape) -> u32 { shape.area() }\nfn main() { assert_eq!(area(&Square(3)), 9); }', 'The borrowed trait object uses dynamic dispatch without requiring a Box allocation.', ['Every conversion to &dyn Trait allocates a separate heap object.','Using dyn Trait requires all implementation methods to be monomorphized for the caller.'], 'Dispatch and allocation are separate choices: &dyn Trait borrows existing storage; Box<dyn Trait> also owns allocated storage.', 'Why is an async method not directly dispatchable through dyn Trait? Compare a generic caller with an explicitly boxed future.')
revise('q-unsafe','What must a safe wrapper establish before this unchecked access?', 'fn first(values: &[u8]) -> Option<u8> {\n    if values.is_empty() { return None; }\n    // SAFETY: the nonempty check proves index 0 is in bounds.\n    Some(unsafe { *values.get_unchecked(0) })\n}\nfn main() { assert_eq!(first(&[]), None); }', 'Every safe call must preserve the preconditions of the internal unsafe operation.', ['Writing unsafe transfers every correctness obligation to the compiler.','A successful test removes the need to justify the unchecked index.'], 'The check establishes bounds for this access. values.first().copied() is a simpler safe alternative; unsafe does not disable borrowing or type checking.', 'Show the safe alternative, then explain why tests and Miri provide evidence rather than a general proof of soundness.')
revise('q-atomics','When is Relaxed suitable for this counter after all worker threads have joined?', 'use std::sync::atomic::{AtomicUsize, Ordering};\nstatic COUNT: AtomicUsize = AtomicUsize::new(0);\nfn main() {\n    let workers: Vec<_> = (0..4).map(|_| std::thread::spawn(|| {\n        COUNT.fetch_add(1, Ordering::Relaxed);\n    })).collect();\n    for worker in workers { worker.join().unwrap(); }\n    assert_eq!(COUNT.load(Ordering::Relaxed), 4);\n}', 'Only the counter value is needed; thread completion supplies the separate join boundary.', ['Relaxed also publishes every unrelated non-atomic write to every reader.','Relaxed becomes sufficient only when there are no concurrent increments.'], 'Atomic increments avoid lost updates; join establishes worker completion. A flag publishing other data needs a separate synchronization argument.', 'Change the counter into a ready flag publishing a payload. Which acquire must observe which release, and what protects the payload’s accesses?',lead='Atomicity and ordering answer different questions. Relaxed preserves the atomic operation without providing publication of unrelated data. Acquire/Release can establish a synchronization relationship when the relevant read observes the release; SeqCst adds ordering guarantees but does not repair an invalid protocol or have one universal performance cost.')
revise('q-deadlock','Which design change directly removes the opposite-lock-order cycle?', '// Worker A acquires first, then second.\n// Worker B acquires second, then first.\n// Both may wait while holding their first lock.', 'Use one documented lock order everywhere, or merge state behind one suitable lock.', ['Replace both mutexes with RwLock while retaining the acquisition order.','Delay the second acquisition by a fixed sleep on each worker.'], 'An ordering rule removes this circular wait if all relevant paths follow it. Sleeps change timing, not the possibility of a cycle.', 'Would an async mutex remove an opposite-order cycle? Discuss reentrant calls, cancellation and lock scope separately.')
revise('q-channels-vs-mutex','What extra contract is needed for a multi-producer work queue?', '// Several producers submit jobs to one worker.\n// The worker processes each accepted message.\n// The input rate can exceed the worker rate.', 'Define capacity, overload behaviour and the required ordering between producers.', ['A channel guarantees one global real-time ordering for concurrent senders.','A mutex-protected Vec automatically supplies capacity limits and wakeups.'], 'A channel models transfer, but does not eliminate capacity, shutdown or ordering design. A shared-state API can also be appropriate for a different access pattern.', 'Explain why per-producer order does not necessarily define a meaningful global order for simultaneous requests.')
revise('q-async-vs-threads','Which execution plan fits sustained CPU-bound image resizing across available cores?', '// 500 images; bounded RAM; 8 available CPU cores.\n// Each resize performs a long calculation without yielding.', 'Use bounded compute parallelism and queue admission sized for the workload.', ['Spawn 500 async tasks and rely on await to parallelize each calculation.','Create one operating-system thread per image regardless of memory limits.'], 'An async runtime can use multiple threads, but spawning tasks alone neither bounds CPU work nor makes a synchronous loop yield.', 'How would the design change for mostly idle sockets? Name what remains bounded in both designs.',rule='Choose concurrency and parallelism from the workload; async tasks still execute on threads.')
revise('q-blocking-async','What does the synchronous read do while the executor polls this task?', 'async fn handler() -> std::io::Result<Vec<u8>> {\n    std::fs::read("big.bin")\n}', 'It occupies the current executor worker until the synchronous call returns.', ['The async keyword automatically schedules std::fs work on a blocking pool.','Calling a synchronous function from async code necessarily causes a panic.'], 'This read does not yield while it runs. On a multi-thread runtime other workers may still progress; measure latency and bound any offloaded work.', 'Can a started spawn_blocking closure be forcefully cancelled by dropping its JoinHandle? Design shutdown for work that may continue.',lead='An async function runs synchronously whenever it is polled until it yields or returns. A blocking call occupies that worker; suspension at await is different and need not occupy a thread. An immediately ready await may not yield. A lock held across suspension can still block competing tasks and create deadlocks.')
revise('q-cancellation','If this future owns buf, what risk follows from dropping it after the read but before store completes?', '// Async pseudocode: socket and store are supplied by the caller.\nlet mut buf = Vec::new();\nsocket.read_buf(&mut buf).await?;\nstore(buf).await?;', 'Consumed bytes may be lost with the dropped future unless their ownership survives cancellation.', ['Dropping any future reverses all earlier socket and database effects.','Cancelling a caller always aborts every spawned task it created.'], 'Cancellation commonly drops this future’s state; it does not roll back completed effects. The storage API’s ownership and commit semantics decide whether retry is safe.', 'Compare dropping a future, dropping a Tokio JoinHandle and explicitly aborting its task. What can still continue after a timeout?')
revise('q-stack-heap','What does moving this Vec guarantee about its elements and allocation?', 'fn main() {\n    let a = vec![7u8; 1024];\n    let pointer = a.as_ptr();\n    let b = a;\n    assert_eq!(b.as_ptr(), pointer);\n    assert_eq!(b.len(), 1024);\n}', 'Ownership transfers without cloning every element or allocating a second buffer.', ['The move must copy exactly three machine words as observable work.','Each element is copied into a newly allocated destination buffer.'], 'Vec has pointer, length and capacity metadata, but its field layout/order and emitted move instructions are not fixed here. The handle need not be physically on a stack; optimization may eliminate a move.', 'How do Vec::clone, a borrowed slice and a moved Vec differ? What changes if the Vec handle is itself a field in a heap allocation?',lead='Storage location and ownership are separate. A Vec handle can be a local, a field inside another allocation or optimized away. For a nonempty u8 vector with allocated capacity, moving the Vec transfers its existing buffer; no fixed count of machine instructions or copied bytes follows.',rule='A move transfers ownership; handle placement and optimized instructions are not language guarantees.',example='fn main() {\n    let before = vec![1u8, 2, 3];\n    let allocation = before.as_ptr();\n    let after = before;\n    assert_eq!(after.as_ptr(), allocation);\n    assert_eq!(after, [1, 2, 3]);\n}',caption='The owned allocation is retained across this move; this does not measure emitted machine instructions.')
revise('q-virtual-memory','What can be concluded from mapping one file read-only into two processes on an OS with shared file-backed pages?', '// OS-level scenario, not a portable Rust guarantee.\n// Two read-only mappings reference the same file.\n// Residency, mapping flags and allocator behaviour are not specified.', 'The OS may share resident file pages, while page tables and other costs remain per mapping.', ['Each mapping must duplicate every file byte in physical RAM immediately.','The mappings guarantee exactly one resident copy of every byte at all times.'], 'Mapping permits sharing; it does not fix RSS, residency, accounting, page-fault behaviour or overhead across operating systems.', 'Contrast virtual address reservation, resident pages and private copy-on-write pages. Which measurement answers your memory-budget question?',lead='Virtual memory maps a process’s addresses to backing storage and physical pages under the operating system’s rules. Reservation, commitment and residency differ. Lazy allocation and shared file pages are common mechanisms, not guarantees of every Rust allocation or a fixed physical cost.',rule='Virtual size, committed memory and residency are different measurements; inspect the actual platform.',example='// Conceptual OS-level sequence; no allocation is performed here.\n// 1. Reserve or map a virtual address range.\n// 2. Access pages under the mapping’s protection rules.\n// 3. Inspect resident/private/shared memory on that OS.\n// File-backed pages may be shared; mappings still have overhead.',caption='This is a conceptual mapping trace, not a promise that Vec::with_capacity reserves virtual pages lazily.')
revise('q-syscalls','What should be investigated in this byte-at-a-time writer?', '// Write implementation and input bytes are provided by the caller.\nfor byte in data {\n    socket.write_all(&[byte])?;\n}', 'Measure tiny-write overhead and consider batching while preserving latency and errors.', ['Adding async syntax alone guarantees that all writes become one syscall.','write_all guarantees this loop has exactly one kernel transition per byte.'], 'Write can be buffered or user-defined. Errors are propagated by ?. Measure the actual boundary; batching still needs partial-write and flush policy.', 'When does flush differ from durability, and what happens to errors discovered while BufWriter is dropped?')
revise('q-tcp-udp','For real-time media, which design addresses packets that arrive after their playback deadline?', '// The receiver can tolerate some missing audio.\n// It must not wait indefinitely for late data.', 'Use a media protocol with deadlines, loss handling, congestion control and suitable transport.', ['Raw UDP automatically discards every packet that is late for the application.','TCP retransmission guarantees every audio frame arrives before its deadline.'], 'UDP preserves datagrams but supplies no playback-deadline policy. The application protocol must handle timeliness, loss, ordering and congestion.', 'Why can QUIC use UDP while still providing reliable streams? Separate substrate from application guarantees.')
revise('q-http-versions','What can TCP packet loss delay for HTTP/2 streams on one connection?', '// Several HTTP/2 streams share one TCP byte stream.\n// A gap prevents delivery of bytes after the missing TCP range.', 'New bytes after the TCP gap, even when they belong to other HTTP/2 streams.', ['Only frames belonging to the HTTP/2 stream that first experienced the loss.','Already delivered application data must be withdrawn from every stream.'], 'TCP delivers bytes in order. Work using already delivered bytes can continue; claiming every stream always stalls is too broad.', 'What does HTTP/3 remove at the transport-stream level, and which shared congestion or connection effects remain?',rule='HTTP/2 shares TCP’s ordered byte delivery; QUIC separates delivery of different streams.')
revise('q-tls','Without certificate verification or another identity check, what security guarantee is missing?', '// A TLS client disables server certificate/hostname verification.\n// No independent pinning or authentication replaces it.', 'The client cannot rely on the TLS connection to authenticate the intended server.', ['TLS record encryption alone proves the requested hostname’s identity.','Disabling verification only changes handshake speed, not trust.'], 'An active interceptor may impersonate the endpoint. Encryption and integrity protect the negotiated connection, whose peer must first be authenticated.', 'What does forward secrecy protect after a long-term key compromise, and what does it not protect on a compromised endpoint?',lead='TLS combines endpoint authentication and protection of traffic under its negotiated protocol. Correct certificate and hostname validation normally authenticates a web server. Forward secrecy limits retrospective exposure from a later long-term key compromise; it is conditional on the handshake and does not protect a compromised live endpoint.')
revise('q-backpressure','What risk remains when an unbounded queue has a producer that persistently outpaces its consumer?', '// Arrival rate exceeds completion rate for a sustained interval.\n// No rejection, upstream rate limit or queue-size bound is present.', 'Pending work and memory can grow without a configured queue limit.', ['The queue silently drops the oldest accepted item at its capacity.','The sender automatically awaits a capacity slot in the unbounded queue.'], 'The outcome may be increasing delay, allocation failure, shutdown or an OOM kill. Unbounded does not promise one specific failure mechanism.', 'Choose between waiting, rejecting and dropping for telemetry versus financial work. How do you bound bytes when messages have different sizes?')
revise('q-acid','Under PostgreSQL Read Committed, can a second SELECT observe a row committed after the first SELECT?', '-- PostgreSQL Read Committed; a concurrent transaction commits an update.\nBEGIN;\nSELECT balance FROM account WHERE id = 7;\n-- Concurrent COMMIT occurs here.\nSELECT balance FROM account WHERE id = 7;\nCOMMIT;', 'Yes; separate commands can observe different committed snapshots.', ['No; BEGIN alone fixes one transaction-wide snapshot at Read Committed.','Only if the second SELECT explicitly takes an exclusive row lock.'], 'This is an engine-specific isolation contract. State the invariant and handle retryable conflicts when choosing stronger isolation.', 'How would an atomic conditional UPDATE protect a nonnegative balance? Compare it with a read-then-write application sequence.',lead='ACID describes distinct transaction properties whose exact guarantees depend on the engine and configuration. Serializable execution is equivalent to some serial order; it may require retries and does not automatically imply external consistency or correct application invariants.',rule='Choose transaction boundaries and isolation for a named invariant on a named database.')
revise('q-indexes','Why should these two PostgreSQL queries be compared with EXPLAIN and representative data?', '-- Index: (tenant_id, kind, at).\nEXPLAIN SELECT * FROM events WHERE tenant_id = 42 AND kind = \'click\';\nEXPLAIN SELECT * FROM events WHERE kind = \'click\';', 'Predicate selectivity, statistics and available scan strategies determine the chosen plan.', ['A non-leading predicate makes every composite B-tree index unusable.','The existence of any matching column forces a full index-only scan.'], 'Leading columns often improve selectivity, but eligibility, skip-scan possibilities and the cheapest plan are different questions.', 'How do row count, visibility, table access and write overhead affect the decision to add another index?')
revise('q-cap','Does read quorum + write quorum > replica count alone prove linearizable reads?', '// N = 5, R = 3, W = 3.\n// Version ordering, concurrent writes and failed partial writes are unspecified.', 'No; intersection alone does not define conflict ordering or handle incomplete operations.', ['Yes; any intersecting quorums implement a complete linearizable protocol.','Yes; the arithmetic also makes every minority partition writable.'], 'Overlapping sets are useful evidence, not a full protocol. CAP concerns availability and linearizability during a partition under specific definitions.', 'Design cart updates under a partition. How will quantities, removals, retries and concurrent adds be merged without silently losing intent?',lead='CAP is about the guarantees a distributed system can provide when communication partitions occur. A cart may use a mergeable design, but that is an explicit product and conflict-resolution choice. Quorum intersection is not by itself proof of linearizability, consensus or last-write correctness.',rule='Specify the consistency model and failure protocol; quorum arithmetic alone is insufficient.',example='// Quorum sketch, not an executable consistency proof:\n// N=5, R=3, W=3 makes every R/W pair intersect.\n// Still specify: version ordering, concurrent writes,\n// partial failures, read repair and partition behaviour.',caption='An overlapping read/write quorum still needs a protocol for versions, concurrency and partial failures.')
revise('q-idempotency','After a timeout on this relative update, what must the client assume without a deduplication contract?', 'POST /accounts/7/balance\n{"add": 10}\n\n// The response is lost. The server may or may not have committed.', 'Retrying can apply the addition twice; a timeout does not prove the first attempt failed.', ['Sending the same body automatically deduplicates every HTTP POST.','A lost response necessarily rolls back the server’s committed operation.'], 'An idempotency key only helps when the server validates request identity and durably/atomically records its relation to the effect and response.', 'What happens if the server crashes between charging and recording the key? Define atomicity, key reuse checks and the retention window.',lead='Retries can repeat an operation whose first outcome is unknown. A sound idempotency design binds a key to the request and outcome, coordinates deduplication with the business effect and defines expiry. Adding a header alone does not create exactly-once execution.',rule='An idempotency key needs an enforced request/outcome contract, not just a header.')
revise('q-caching','With no request coalescing, what can concurrent misses for one expired hot key cause?', '// Many requests miss the same key before any refill completes.\n// Cache lookup and origin loading are separate operations.', 'Several overlapping origin loads, increasing pressure during the refill interval.', ['The cache API automatically serializes every application’s refill function.','A TTL guarantees that only one caller can observe an expired entry.'], 'A stampede is possible, not a claim that every request always reaches the origin. Use a bounded single-flight or another explicit refresh policy.', 'What happens to single-flight waiters when the refresh fails or its initiating request is cancelled? Define stale-data policy too.')
revise('q-complexity','Which statement describes repeated Vec::push with ordinary geometric growth assumptions?', 'fn main() {\n    let mut values = Vec::new();\n    for n in 0..100 { values.push(n); }\n    assert_eq!(values.len(), 100);\n}', 'Push is amortized O(1); a capacity-growing operation may relocate existing elements.', ['Every push has worst-case O(1) time regardless of capacity or allocator.','Each push is O(log n) because Vec stores values in a balanced tree.'], 'Amortized cost differs from one operation’s worst case. Reservation can avoid reallocations within the reserved capacity, not every future allocation.', 'Why might a small contiguous scan beat a structure with a better asymptotic bound? State n, cache locality and benchmark conditions.')
revise('q-hashmap','Why review a fast non-cryptographic hasher for attacker-controlled string keys?', '// An HTTP service accepts arbitrary client-provided strings as keys.\n// A predictable fast hasher replaces the default HashMap hasher.', 'Adversarial collision patterns can worsen lookup cost and create denial-of-service risk.', ['HashMap rejects String keys whenever its hasher is customized.','Choosing a faster hasher guarantees constant-time lookup for every input.'], 'Consider the specific hasher, threat model and quotas. Default hashing policy is not a permanent promise of one named algorithm.', 'How do entry limits and input-size limits complement collision resistance? Compare trusted integer IDs with public untrusted strings.',example='use std::collections::HashMap;\nfn main() {\n    let mut counts = HashMap::new();\n    for key in ["accept", "accept", "content-type"] {\n        *counts.entry(key).or_insert(0) += 1;\n    }\n    assert_eq!(counts.get("accept"), Some(&2));\n}',caption='The default HashMap builder avoids committing this lesson to one permanent hashing algorithm.')
revise('q-testing-strategy','Which technique directly explores many malformed byte sequences for this parser?', '// A parser accepts untrusted binary input.\n// Known examples and deterministic regression tests already exist.', 'A focused fuzz target with assertions, resource bounds and retained counterexamples.', ['A single integration test proves correctness for every malformed byte sequence.','Line coverage alone establishes that every parser invariant is checked.'], 'No technique is guaranteed to find a particular crash first. Combine known regression tests, properties, fuzzing and boundary integration tests.', 'Why can encode/decode roundtrip still pass if both share the same bug? Add an independent oracle or known external vectors.',lead='Examples, generated properties, fuzz targets and integration tests provide different evidence. None guarantees which bug is found first or that untested invariants hold. State what each test checks, then preserve minimized failures as regressions.',rule='Choose tests for named failure modes and independent evidence; test labels alone prove little.')
revise('q-api-design','Why can adding a variant to an already public exhaustive enum break downstream crates?', 'pub enum Status { Ready, Failed }\n// Another crate matches Status exhaustively.', 'Existing exhaustive matches may need another branch; evolution policy must be planned in advance.', ['Adding a variant is unconditionally non-breaking because old variants remain.','Applying non_exhaustive later is always a compatible fix for existing callers.'], '#[non_exhaustive] can reserve extension room when applied as part of the original contract. Adding it later can itself break exhaustive downstream code.', 'Contrast adding a required trait method with adding a defaulted one. Which coherence or name-resolution changes can still affect downstream users?',lead='Public API evolution includes downstream implementations and exhaustive matches, not just function names. Adding a required trait method or an exhaustive enum variant can break users. non_exhaustive and sealing are design choices with their own compatibility and flexibility costs.')
revise('q-perf-profiling','Before claiming production performance from this command, what should be checked?', 'cargo build\n# Then run a timing comparison.', 'Verify the actual profile, optimization settings and representative measurement conditions.', ['Every development profile has identical timing to a release profile.','Running cargo bench is the only way to obtain any useful performance evidence.'], 'Cargo defaults differ, but profiles are configurable. Development results can diagnose development behaviour; they do not establish production performance or a fixed speed ratio.', 'How would you separate cold build, warm build, initialization and steady-state execution? Record variance and verify output correctness.',lead='A benchmark measures a specific artifact and workload. Cargo profile names have defaults that can be changed; there is no universal debug-to-release speed ratio. Match production settings when answering a production question, and separate compilation, initialization and steady-state execution.')
revise('q-ffi-abi','Why is this raw pointer invalid after the CString is dropped?', '// Declaration fragment: a matching foreign c_use implementation is required.\nuse std::ffi::{CString, c_char};\nunsafe extern "C" { fn c_use(value: *const c_char); }\nfn main() {\n    let name = CString::new("crab").unwrap();\n    let ptr = name.as_ptr();\n    drop(name);\n    // Do not execute: unsafe { c_use(ptr) }; would use a dangling pointer.\n}', 'The pointer does not own the buffer or extend the CString allocation’s lifetime.', ['Calling as_ptr transfers the CString buffer to the foreign function.','Using extern C makes every pointer valid until the process exits.'], 'Keep the owner alive for the entire foreign use, or use an explicit ownership-transfer API with a matching release contract. repr(C) alone does not establish pointer validity.', 'What changes if the foreign function retains the pointer after returning? Specify who allocates, who frees and which allocator is used.')
revise('q-two-sum-rust','Why must this scan look up the complement before inserting the current index?', 'use std::collections::HashMap;\nfn two_sum(values: &[i32], target: i32) -> Option<(usize, usize)> {\n    let mut seen = HashMap::new();\n    for (j, &value) in values.iter().enumerate() {\n        let needed = i64::from(target) - i64::from(value);\n        if let Some(&i) = seen.get(&needed) { return Some((i, j)); }\n        seen.entry(i64::from(value)).or_insert(j);\n    }\n    None\n}\nfn main() {\n    assert_eq!(two_sum(&[3, 3], 6), Some((0, 1)));\n    assert_eq!(two_sum(&[3], 6), None);\n}', 'Only an earlier index can match, so one element is not reused as both operands.', ['The lookup order guarantees all possible matching pairs are returned.','Inserting first prevents all arithmetic overflow in the complement.'], 'The example uses i64 arithmetic for i32 inputs. It returns the first matching second index, preserving the earliest stored first index; absence is None.', 'Trace duplicates, no match and i32 extremes. What deterministic tie-breaking rule does this implementation actually provide?',example='use std::collections::HashMap;\nfn two_sum(values: &[i32], target: i32) -> Option<(usize, usize)> {\n    let mut seen = HashMap::new();\n    for (j, &value) in values.iter().enumerate() {\n        let needed = i64::from(target) - i64::from(value);\n        if let Some(&i) = seen.get(&needed) { return Some((i, j)); }\n        seen.entry(i64::from(value)).or_insert(j);\n    }\n    None\n}\nfn main() {\n    assert_eq!(two_sum(&[3, 3], 6), Some((0, 1)));\n    assert_eq!(two_sum(&[3], 6), None);\n}',caption='Lookup before insertion enforces distinct indices; widening i32 arithmetic avoids complement overflow.')
revise('q-lru-design','Which invariant supports O(1) expected lookup and recency updates in a full LRU design?', '// Design sketch: map K -> node ID, plus a doubly linked recency list.\n// get/put moves one existing node; eviction removes the tail.', 'The map locates a node directly and the list unlinks/relinks that node in constant time.', ['A HashMap alone stores a permanent total order of most-recent use.','A VecDeque scan gives worst-case O(1) lookup for arbitrary keys.'], 'A standard VecDeque prototype can illustrate policy with O(n) scans. A production O(1)-update design also needs valid stable node IDs, edge handling and a capacity contract.', 'What happens at capacity zero, when a key is updated, and when an arena slot is reused? Explain how stale node identities are prevented.')
revise('q-parser-design','What must a byte span into a UTF-8 source preserve before it becomes a &str slice?', 'struct Span { start: usize, end: usize }\nfn main() {\n    let source = "café";\n    let span = Span { start: 3, end: 5 };\n    assert_eq!(source.get(span.start..span.end), Some("é"));\n}', 'The range must be ordered, in bounds and aligned to UTF-8 character boundaries.', ['Every byte offset is automatically a valid Unicode scalar boundary.','Storing a Span automatically extends the lifetime of its source buffer.'], 'Spans are coordinates, not ownership or proof of validity. Keep the correct source/version and use checked slicing at trust boundaries.', 'How do byte offsets, Unicode scalar positions, grapheme clusters and editor UTF-16 selections differ?')
revise('q-debugging-session','What failure does average(&[]) reveal in this implementation?', 'fn average(values: &[u32]) -> u32 {\n    let total: u32 = values.iter().sum();\n    total / values.len() as u32\n}\nfn main() { println!("{}", average(&[])); }', 'The denominator is zero, so integer division panics.', ['Borrowing an empty slice is itself undefined behaviour.','The compiler rejects every call passing an empty slice to this function.'], 'Define empty-input behaviour before patching. Also investigate sum overflow, narrowing len and the intended rounding policy.', 'Return Option<u32> with a safely widened accumulator, then test empty input, maxima and truncation of a fractional mean.')
revise('q-tradeoff-communication','Which answer connects a proposed design to a falsifiable decision criterion?', '// Requirement: 16 MiB work budget, offline operation, bounded inputs.\n// Compare two implementations under those same constraints.', 'Choose a candidate, state the accepted cost and name evidence that would change the choice.', ['List many implementation features without tying them to user constraints.','Claim the faster asymptotic bound settles latency at every input size.'], 'A useful recommendation states constraints, alternatives, a measurable outcome and the condition for revisiting it.', 'What metric would reveal that your chosen queue capacity harms tail latency? How would you gather that evidence?')
revise('q-requirements','Which clarification changes the storage design before implementation?', 'struct Requirements {\n    max_items: usize,\n    survives_restart: bool,\n    max_loss_seconds: u32,\n}', 'Ask whether an acknowledged write must survive restart and how much loss is acceptable.', ['Treat surviving restart as equivalent to keeping a value in process memory.','Choose a data structure before establishing input size or failure semantics.'], 'Scale and failure requirements determine viable designs. Define acknowledgement, durability, latency and trust boundaries in observable terms.', 'What changes if offline edits must survive a crash, but shared rooms deliberately expire and can end on server restart?')
revise('q-code-review','Which API change handles empty input without returning a fabricated value?', 'fn first(values: &[String]) -> &str {\n    values[0].as_str()\n}', 'Return Option<&str> using values.first().map(String::as_str).', ['Clone values[0] before indexing to remove the empty-input failure.','Mark the function unsafe so indexing no longer checks its bounds.'], 'The returned borrow can remain tied to the input. Option expresses absence; cloning does not fix the invalid index.', 'When would Result be a better contract than Option? Add tests for empty input and a Unicode first string.')
revise('q-postmortem','Which action directly reduces recurrence of an unbounded-queue incident?', '// Trigger: arrival rate exceeded worker throughput.\n// Detection gap: memory and queue age were not monitored.', 'Bound admission, define overload behaviour and verify it under sustained excess load.', ['Record the incident timeline but leave admission and monitoring unchanged.','Ask operators to remember to restart the service earlier next time.'], 'A durable control changes a failure mechanism and has an owner and a verification method. Preserve a blameless account of contributing conditions.', 'What would demonstrate the fix protects users during the next overload rather than merely improving average throughput?')
assert len(changes)==40 and len(set(changes))==40
Path(__file__).with_name('revised-ids.json').write_text(json.dumps(changes,indent=2)+'\n')
print('Revised',len(changes),'existing interview questions; correct-answer indices preserved')
